lib = '''import numpy as np
from collections import Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def nonbg_cells(grid, bg=None):
    """Cells (r, c) whose color differs from the background (default: most common color)."""
    if bg is None: bg = background(grid)
    return [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != bg]

def components(grid, bg=None):
    """The 8-connected components of non-background cells, each a list of (r, c)."""
    if bg is None: bg = background(grid)
    cells = set(nonbg_cells(grid, bg)); comps = []; seen = set()
    for cell in sorted(cells):
        if cell in seen: continue
        stack = [cell]; comp = []
        while stack:
            x = stack.pop()
            if x in seen: continue
            seen.add(x); comp.append(x)
            r, c = x
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    y = (r + dr, c + dc)
                    if y in cells and y not in seen: stack.append(y)
        comps.append(comp)
    return comps

def bbox(cells):
    """The (top, left, height, width) bounding box of a list of (r, c) cells."""
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    return min(rs), min(cs), max(rs) - min(rs) + 1, max(cs) - min(cs) + 1

def largest_component_block(grid, bg=None):
    """The (top, left, subgrid) of the bounding box of the largest non-background component."""
    comp = max(components(grid, bg), key=len)
    top, left, h, w = bbox(comp)
    return top, left, [row[left:left + w] for row in grid[top:top + h]]

def stamp(grid, block, r, c, tr, tc):
    """A copy of the grid with block stamped so its (tr, tc) cell lands at (r, c); clipped at the edges."""
    out = [row[:] for row in grid]
    for i in range(len(block)):
        for j in range(len(block[0])):
            rr, cc = r - tr + i, c - tc + j
            if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
                out[rr][cc] = block[i][j]
    return out
